// This file should NOT export expectedEsModuleGlobs or expectedCompiledWasmGlobs
// The PR #2597 removed these unused exports

/**
 * Check: Verify that `expectedEsModuleGlobs` and `expectedCompiledWasmGlobs` 
 * are NOT exported from worker-additional-module-allowlist.ts.
 * 
 * Before PR: These functions WERE exported (test fails)
 * After PR: These functions are NOT exported (test passes)
 */

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const filePath = resolve(__dirname, 'tools/worker-additional-module-allowlist.ts');
const content = readFileSync(filePath, 'utf-8');

// Check that the unused glob helpers are NOT exported
const hasExpectedEsModuleGlobs = /export\s+(?:function|const)\s+expectedEsModuleGlobs/.test(content);
const hasExpectedCompiledWasmGlobs = /export\s+(?:function|const)\s+expectedCompiledWasmGlobs/.test(content);

if (hasExpectedEsModuleGlobs) {
	console.error('FAIL: expectedEsModuleGlobs should NOT be exported');
	process.exit(1);
}

if (hasExpectedCompiledWasmGlobs) {
	console.error('FAIL: expectedCompiledWasmGlobs should NOT be exported');
	process.exit(1);
}

console.log('PASS: Unused glob helpers are not exported');

